# NEXA Mystery and Long-Form Narrative Phase 10 Test Script

Set-Location $PSScriptRoot

python -c "from mystery_engine import MysteryEngine; from mystery_seed_data import create_warehouse_fire_mystery; engine = MysteryEngine(); mystery, evidence_items = create_warehouse_fire_mystery(); engine.add_mystery(mystery); [engine.add_evidence(mystery.id, evidence) for evidence in evidence_items]; print('NEXA Phase 10 Mystery Test'); print(f'Mystery: {mystery.title}'); print(f'Initial state: {mystery.state.value}'); print(); [print(f'Day {day}: {len(engine.process_day(day))} story beat(s) executed | State: {mystery.state.value}') for day in [1, 3, 7, 14, 23, 31, 47]]; print(); print('Visible evidence after Day 47:'); [print(f'  - {item['title']} | reliability={item['reliability']} | visibility={item['visibility']}') for item in engine.get_visible_evidence(mystery.id)]; print(); blocked = engine.process_day(60, audience_connected_clues=False); print(f'Day 60 without audience clue connection: {len(blocked)} story beat(s) executed | State: {mystery.state.value}'); resolved = engine.process_day(60, audience_connected_clues=True); print(f'Day 60 with audience clue connection: {len(resolved)} story beat(s) executed | State: {mystery.state.value}'); print(); print('Narrative events:'); [print(f'  Day {item['simulation_day']}: {item['title']} -> {item['state_after_event']}') for item in engine.narrative_events]; print(); print('PASS: The mystery remained dormant between scheduled beats while the world could continue running.')"
